from __future__ import annotations

import math
from typing import Any

import numpy as np
from shapely import lib
from shapely.geometry import LineString, Point, Polygon

_REL_TOL = 1e-10

def _as_2d_points(coords) -> np.ndarray:
    arr = np.asarray(coords, dtype=np.float64)
    if arr.ndim == 2 and arr.shape[1] >= 2:
        return arr[:, :2]
    if arr.ndim == 1 and arr.size >= 2:
        return arr[:2].reshape(1, 2)
    return np.empty((0, 2), dtype=np.float64)

def _clean_ring(coords) -> np.ndarray:
    arr = _as_2d_points(coords)
    if len(arr) == 0:
        return arr
    keep = np.ones(len(arr), dtype=bool)
    prev = arr[0]
    for i in range(1, len(arr)):
        if arr[i,0] == prev[0] and arr[i,1] == prev[1]:
            keep[i] = False
        else:
            prev = arr[i]
    arr = arr[keep]
    if len(arr) > 1 and arr[0,0] == arr[-1,0] and arr[0,1] == arr[-1,1]:
        arr = arr[:-1]
    return arr

def _unit(dx, dy):
    scale = max(abs(dx), abs(dy))
    if scale == 0.0 or not np.isfinite(scale):
        return None
    x = dx / scale
    y = dy / scale
    norm = math.hypot(x, y)
    return x / norm, y / norm

def _minimum_rectangle(coords):
    coords = _clean_ring(coords)
    n = len(coords)
    if n < 3:
        return None
    ref = coords[0]
    rel = coords - ref
    best = None
    for i in range(n):
        j = (i + 1) % n
        u = _unit(rel[j,0] - rel[i,0], rel[j,1] - rel[i,1])
        if u is None:
            continue
        ux, uy = u
        vx, vy = -uy, ux
        xp = rel[:,0]*ux + rel[:,1]*uy
        yp = rel[:,0]*vx + rel[:,1]*vy
        minx = float(xp.min()); maxx = float(xp.max())
        miny = float(yp.min()); maxy = float(yp.max())
        area = (maxx-minx)*(maxy-miny)
        if not np.isfinite(area):
            continue
        if best is None or area < best[0]:
            best = (area, ux, uy, vx, vy, minx, maxx, miny, maxy)
    if best is None:
        return None
    area, ux, uy, vx, vy, minx, maxx, miny, maxy = best
    pad = np.spacing(max(abs(minx), abs(maxx), abs(miny), abs(maxy), 1.0)) * 8.0
    minx -= pad; maxx += pad; miny -= pad; maxy += pad
    corners = np.array([
        [ref[0] + minx*ux + miny*vx, ref[1] + minx*uy + miny*vy],
        [ref[0] + minx*ux + maxy*vx, ref[1] + minx*uy + maxy*vy],
        [ref[0] + maxx*ux + maxy*vx, ref[1] + maxx*uy + maxy*vy],
        [ref[0] + maxx*ux + miny*vx, ref[1] + maxx*uy + miny*vy],
    ], dtype=np.float64)
    corners = np.vstack([corners, corners[0]])
    return Polygon(corners)

def _fallback(geometry):
    if geometry is None:
        return None
    if getattr(geometry, "is_empty", False):
        return Polygon()
    hull = geometry.convex_hull
    if hull.is_empty:
        return Polygon()
    gt = hull.geom_type
    if gt == "Point":
        return Point(hull.x, hull.y)
    if gt == "LineString":
        return LineString(hull.coords)
    if gt == "Polygon":
        rect = _minimum_rectangle(hull.exterior.coords)
        if rect is not None:
            return rect
        return hull
    # MultiPoint or unexpected: extract coordinates
    coords = np.asarray(hull.coords, dtype=np.float64) if hasattr(hull, "coords") else None
    if gt == "MultiPoint" and coords is not None:
        coords = _clean_ring(coords)
        if len(coords) == 0:
            return Polygon()
        if len(coords) == 1:
            return Point(coords[0])
        # determine collinearity
        d = coords[1:] - coords[0]
        if np.all(np.abs(d[:,0]*d[0,1] - d[:,1]*d[0,0]) <= 1e-12 * max(1.0, np.abs(d).max())):
            # extremes along primary axis
            t = d[:,0]*d[0,0] + d[:,1]*d[0,1]
            idx = [int(np.argmin(t)), int(np.argmax(t))]
            return LineString([coords[idx[0]], coords[idx[1]]])
        rect = _minimum_rectangle(coords)
        if rect is not None:
            return rect
    return hull

def _compute(geometry):
    if geometry is None:
        return None
    fallback = _fallback(geometry)
    try:
        geos_result = lib.oriented_envelope(geometry)
    except Exception:
        return fallback
    if geos_result is None:
        return fallback
    if fallback is None:
