    if fallback.geom_type != "Polygon" or geos_result.geom_type != "Polygon":
        return fallback
    if not fallback.is_empty and np.isfinite(fallback.area) and np.isfinite(geos_result.area):
        target = fallback.area
        if geos_result.area <= target * (1.0 + _REL_TOL):
            return geos_result
    return fallback

_oriented_envelope_ufunc = np.frompyfunc(_compute, 1, 1)

def oriented_envelope(geometry, **kwargs):
    return _oriented_envelope_ufunc(geometry, **kwargs)

